import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import {
  CommonTopicList,
  FaqList,
  InsertFeedbackReq,
  InsertFeedbackRes,
  KeyWordList,
  ModuleImageUpload,
  ModuleIU,
  ModuleIURes,
  ModuleList,
  SubModuleList,
} from '../../interfaces/helpcenter.interface';
import { TostbarService } from '../../../core/services/tost/tostbar.service';

@Injectable({
  providedIn: 'root',
})
export class HelpcenterService {
  constructor(private http: HttpClient, private tost: TostbarService) { }

  async getCommonTopics(): Promise<KeyWordList[]> {
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.get<KeyWordList[]>(
          `${environment.cloudUrl}${environment.coreservice}/helpcenter/getcommontopics`
        )
      );
    } catch (error) {
      console.error('error', error);
      res = [];
    }
    return res;
  }

  async getModuleList(nKeyid: number = 0): Promise<ModuleList[]> {
    let res: any = [];

    const params = new HttpParams().set('nKeyid', nKeyid);

    try {
      res = await firstValueFrom(
        this.http.get<ModuleList[]>(
          `${environment.cloudUrl}${environment.coreservice}/helpcenter/getmodulelist`,
          {
            params,
          }
        )
      );
    } catch (error) {
      console.error('error', error);
      res = [];
    }
    return res;
  }

  async getSubModuleList(
    nMainid: string,
    nKeyid: number = 0
  ): Promise<SubModuleList[]> {
    let res: any = [];

    const params = new HttpParams()
      .set('nMainid', nMainid)
      .set('nKeyid', nKeyid);
    try {
      res = await firstValueFrom(
        this.http.get<SubModuleList[]>(
          `${environment.cloudUrl}${environment.coreservice}/helpcenter/getsubmodulelist`,
          {
            params,
          }
        )
      );
    } catch (error) {
      console.error('error', error);
      res = [];
    }
    return res;
  }

  async getfaqlist(cQType: string): Promise<FaqList[]> {
    let res: any = [];
    const params = new HttpParams()
      .set('cQType', cQType);
    try {
      res = await firstValueFrom(
        this.http.get<FaqList[]>(
          `${environment.cloudUrl}${environment.coreservice}/helpcenter/getfaqlist`, {
          params,
        }
        )
      );
    } catch (error) {
      console.error('error', error);
      res = [];
    }
    return res;
  }

  async insertFeedback(args: InsertFeedbackReq): Promise<InsertFeedbackRes> {
    try {
      const res: InsertFeedbackRes = await firstValueFrom(
        this.http.post<InsertFeedbackRes>(
          `${environment.uploadservice}/fileconvert/insertfeedback`,
          args
        )
      );
      return res;
    } catch (err: any) {
      console.error('error', err);
      this.tost.openSnackBar(err.message, 'E');
      return { msg: -1, value: 'failed' };
    }
  }

  async getkeywords(cKey: string): Promise<KeyWordList[]> {
    let res: any = [];

    const params = new HttpParams().set('cKey', cKey);
    try {
      res = await firstValueFrom(
        this.http.get<KeyWordList[]>(
          `${environment.cloudUrl}${environment.coreservice}/helpcenter/getkeywords`,
          {
            params,
          }
        )
      );
    } catch (error) {
      console.error('error', error);
      res = [];
    }
    return res;
  }


  
  async module_iu(args: ModuleIU): Promise<ModuleIURes> {
    try {
      return await firstValueFrom(
        this.http.post<ModuleIURes>(
          `${environment.cloudUrl}${environment.coreservice}/helpcenter/module_iu`,
          args
        )
      );
    } catch (error: any) {
      console.error('error', error);
      return { msg: -1 , value: error.message}
    }
  }

  // send submodule id & parent id as parmaerers


  async sub_module_iu(args: SubModuleList): Promise<SubModuleList> {
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.post<SubModuleList>(
          `${environment.cloudUrl}${environment.coreservice}/helpcenter/sub_module_iu`,
          args
        )
      );
    } catch (error) {
      console.error('error', error);
      res = [];
    }
    return res;
  }

  //sub_module_detail//

  async getsubmodule_detail(nSMid: string): Promise<SubModuleList> {
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.get<SubModuleList>(`${environment.cloudUrl}${environment.coreservice}/helpcenter/sub_module_detail`, {
          params: { nSMid: nSMid }
        })
      );
    } catch (error) {
      console.error('error', error);
      res = [];
    }
    return res;
  }

   async moduleimageUpload(mdl: FormData): Promise<ModuleImageUpload> {
      try {
        const res = await firstValueFrom(
          this.http.post<any>(
            `${environment.uploadservice}/helpcenter/upload-image`, mdl)
        );
        if (res.msg == -1) {
          this.tost.openSnackBar(`Image Upload failed ${res.error}`, 'E');
          return { msg: -1, error: res.error, value: '' };
        }
        else {
          return res;
        }
      } catch (err: any) {
        this.tost.openSnackBar(`Image Upload failed ${err}`, 'E');
        return { msg: -1, error: err, value: '' };
      }
    }

  async searchSMid(nSMid: string): Promise<boolean> {
    let res: any = [];

    try {
      res = await firstValueFrom(
        this.http.post<boolean[]>(
          `${environment.cloudUrl}${environment.coreservice}/helpcenter/search_key`,
          { nSMid: nSMid }
        )
      );
    } catch (error) {
      console.error('error', error);
      res = [];
    }
    return res;
  }
}
